(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const guest=(new URLSearchParams(location.search).get('guest')||new URLSearchParams(location.search).get('name')||'').trim().slice(0,160);
$('#guest-name').textContent=guest||'ඔබට සහ පවුලේ සැමට';$('#lm-name').value=guest;
const welcome=document.createElement('p');welcome.id='guest-hero';welcome.textContent=guest?`${guest}, ඔබට සාදර ඇරයුමයි!`:'';$('#hero h1').parentElement.after(welcome);
const music=$$('audio')[1],intro=$$('audio')[0],musicButton=$('button[aria-label="Play music"]');
function musicState(){musicButton.setAttribute('aria-pressed',String(!music.paused));musicButton.setAttribute('aria-label',music.paused?'Play music':'Mute music');musicButton.title=music.paused?'Play music':'Mute music';musicButton.innerHTML=music.paused?'♫':'♪';}
musicButton.addEventListener('click',()=>{if(music.paused){music.play().then(musicState).catch(()=>{});}else{music.pause();intro.pause();musicState();}});
music.volume=.35;intro.volume=.4;
$('#opening button[aria-label="Open invitation"]').addEventListener('click',()=>{$('#opening').classList.add('closed');$('#opening').setAttribute('aria-hidden','true');$('#opening').inert=true;document.body.classList.add('invitation-open');intro.play().catch(()=>{});music.play().then(musicState).catch(()=>{});$('#hero').setAttribute('tabindex','-1');$('#hero').focus({preventScroll:true});});
const end=new Date('2027-01-21T10:00:00+05:30').getTime();const numbers=$$('#countdown .tabular-nums');function tick(){let n=Math.max(0,Math.floor((end-Date.now())/1000));[Math.floor(n/86400),Math.floor(n/3600)%24,Math.floor(n/60)%60,n%60].forEach((v,i)=>numbers[i].textContent=String(v).padStart(2,'0'));}tick();setInterval(tick,1000);
const form=$('#rsvp form'),choices=$$('form button').filter(b=>!b.hasAttribute('aria-label')&&b.type==='button');let attending=true,count=1;
const decrease=$('[aria-label="Decrease guest count"]'),increase=$('[aria-label="Increase guest count"]'),countEl=decrease.nextElementSibling;
function select(v){attending=v;choices.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===(v?0:1))));decrease.parentElement.parentElement.hidden=!v;}
choices[0].onclick=()=>select(true);choices[1].onclick=()=>select(false);select(true);
decrease.onclick=()=>{count=Math.max(1,count-1);countEl.textContent=count;};increase.onclick=()=>{count=Math.min(50,count+1);countEl.textContent=count;};
const note=document.createElement('p');note.id='form-note';note.textContent='ඔබගේ පිළිතුර Dumindu වෙත WhatsApp හරහා යවන්න.';form.append(note);
form.addEventListener('submit',e=>{e.preventDefault();const name=$('#lm-name').value.trim();if(!name){$('#lm-name').focus();return;}const msg=`Wedding RSVP — Malsha & Dumindu\n21 January 2027\nName: ${name}\n${attending?'Happily attending':'Unable to attend'}${attending?'\nGuests: '+count:''}`;window.open('https://wa.me/94768594375?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer');});
const calendar=$('#events button[aria-haspopup]');calendar.removeAttribute('aria-controls');calendar.onclick=()=>{let menu=$('.calendar-options');if(menu){menu.remove();calendar.setAttribute('aria-expanded','false');return;}menu=document.createElement('div');menu.className='calendar-options';const google=document.createElement('a');google.textContent='Google Calendar';google.target='_blank';google.rel='noopener';google.href='https://calendar.google.com/calendar/render?action=TEMPLATE&text=Malsha+%26+Dumindu+Wedding&dates=20270121T043000Z/20270121T103000Z&location=The+Epitome+Hotel,+Jewel+Banquet+Hall,+Kurunegala';const ics=document.createElement('a');ics.textContent='Apple / Outlook (.ics)';ics.download='Malsha-Dumindu-Wedding.ics';ics.href='wedding.ics';menu.append(google,ics);calendar.parentElement.append(menu);calendar.setAttribute('aria-expanded','true');};
const viewer=$('#photo-viewer');$$('#gallery img').forEach(img=>{img.tabIndex=0;img.setAttribute('role','button');img.setAttribute('aria-label','View '+img.alt);const show=()=>{viewer.querySelector('img').src=img.src;viewer.showModal();};img.onclick=show;img.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show();}};});viewer.querySelector('button').onclick=()=>viewer.close();viewer.onclick=e=>{if(e.target===viewer)viewer.close();};
const nav=$$('nav a');const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(!e.isIntersecting)return;nav.forEach(a=>{const active=a.hash==='#'+e.target.id;a.style.background=active?'#984d6a':'transparent';a.style.color=active?'#fff9fa':'#984d6a';a.setAttribute('aria-current',String(active));});});},{rootMargin:'-20% 0px -50% 0px'});$$('#hero,#events,#gallery,#venue,#rsvp').forEach(e=>observer.observe(e));
// Keep the original bilingual invitation controls with localized visible text.
const dict={'සාදර ඇරයුමයි !':'You are warmly invited!','විවෘත කරන්න':'Open invitation','මල්ෂා':'Malsha','දුමින්දු':'Dumindu','සහ':'&','රූපසිංහ මහතාගේ සහ\nනදීකා ගුණවර්ධන මහත්මියගේ\nආදරණීය දියණිය':'The beloved daughter of\nMr. Roopasingha &\nMrs. Nadeeka Gunawardhana','සුජිත් ද සිල්වා මහතාගේ සහ\nඅයේෂා සේනානායක මහත්මියගේ\nආදරණීය පුතු':'The beloved son of\nMr. Sujith De Silva &\nMrs. Ayesha Senanayake','චාරිත්‍රානුකූලව අතිනත ගැනීමේ ප්‍රීතිය නිමිත්තෙන්':'Together with our families, we joyfully invite you to celebrate our wedding.','ජනවාරි':'January','බ්‍රහස්පතින්දා':'Thursday','පෙ.ව. 10.00 සිට ප.ව. 4.00 දක්වා':'10:00 AM – 4:00 PM','හෝටල් පරිශ්‍රයේ දී පැවැත්වෙන මංගල උත්සවයට':'Join us for our wedding celebration','ඔබව අපි ගෞරවයෙන් ආරාධනා කරන්නෙමු.':'Your presence would mean the world to us.','(පෝරුවේ චාරිත්‍ර පෙ.ව. 10.14 ට)':'(Poruwa ceremony at 10:14 AM)','සුබ මොහොත එළඹෙන තුරු':'Until our special day','දින':'Days','පැය':'Hours','මිනිත්තු':'Minutes','තත්පර':'Seconds','2027 ජනවාරි 21 බ්‍රහස්පතින්දා':'Thursday, 21 January 2027','උත්සව විස්තර':'The celebration','මංගල උත්සවය සහ පෝරුවේ චාරිත්‍රය':'Wedding & Poruwa ceremony','පෝරුවේ චාරිත්‍රය: පෙ.ව. 10.14 ට':'Poruwa ceremony: 10:14 AM','දිවා භෝජනය: ප.ව. 12.07 ට':'Lunch: 12:07 PM','උත්සවයේ අවසානය: ප.ව. 3.51 ට':'Farewell: 3:51 PM','දිනය සුරකින්න':'Save the date','ඔබගේ දින දර්ශනයට එක් කරන්න':'Add to your calendar','ඡායාරූප එකතුව':'Our moments','උත්සව ස්ථානය':'The venue','කුරුණෑගල':'Kurunegala','සිතියමෙන් බලන්න':'Get directions','පැමිණීම දන්වන්න':'Kindly RSVP','ඔබගේ පැමිණීම අපට මහත් සතුටකි. කරුණාකර කලින් දන්වන්න.':'We would love to celebrate with you. Please let us know if you can join us.','සම්පූර්ණ නම':'Full name','සහභාගි වෙනවාද?':'Will you be joining us?','සතුටින් සහභාගි වෙමි':'Joyfully accepts','සහභාගි විය නොහැක':'Regretfully declines','පැමිණෙන ගණන':'Number of guests','පිළිතුර යවන්න':'Send via WhatsApp','ආදරයෙන්, දෙපවුලේ ආරාධනයයි':'With love, from both our families','ඔබගේ පිළිතුර Dumindu වෙත WhatsApp හරහා යවන්න.':'Send your response to Dumindu via WhatsApp.'};
const textNodes=[];const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const n=walker.currentNode;if(dict[n.textContent.trim()])textNodes.push({node:n,si:n.textContent,en:dict[n.textContent.trim()]});}
const headings=$$('span').filter(n=>n.textContent==='idor werhquhs');
const languageButtons=$$('[aria-label="Invitation language"] button');let lang='si';function language(l){lang=l;document.documentElement.lang=l;textNodes.forEach(t=>t.node.textContent=l==='en'?t.en:t.si);headings.forEach(h=>{h.textContent=l==='en'?'You are invited':'idor werhquhs';h.style.fontFamily=l==='en'?'Georgia,serif':'var(--font-lm-heading),serif';});languageButtons.forEach(b=>b.setAttribute('aria-pressed',String(b.textContent.trim()===(l==='si'?'සිං':'EN'))));$('#guest-welcome').firstChild.textContent=l==='en'?'Especially for':'ආදරණීය ';$('#guest-name').textContent=guest||(l==='en'?'You & your family':'ඔබට සහ පවුලේ සැමට');welcome.textContent=guest?(l==='en'?`${guest}, you are warmly invited!`:`${guest}, ඔබට සාදර ඇරයුමයි!`):'';$('#lm-name').placeholder=l==='en'?'Your name':'ඔබගේ නම';}
languageButtons.forEach(b=>b.onclick=()=>language(b.textContent.trim()==='EN'?'en':'si'));
const floating=document.createElement('div');floating.className='lang-switch';floating.setAttribute('aria-label','Invitation language');['සිං','EN'].forEach((t,i)=>{const b=document.createElement('button');b.textContent=t;b.type='button';b.setAttribute('aria-pressed',String(!i));b.onclick=()=>{language(i?'en':'si');floating.querySelectorAll('button').forEach((x,j)=>x.setAttribute('aria-pressed',String(i===j)));};floating.append(b);});document.body.append(floating);
})();
